const CACHE='dynasty-desk-v8';const ASSETS=['./','./index.html','./styles.css','./app.js','./commissioner.html','./commissioner.js','./admin.css','./domain/models.js','./domain/simulation.js','./domain/permissions.js','./domain/audit.js','./application/league-workflow.js','./application/admin-summary.js','./stores/local.js','./stores/game-store.js','./stores/sharepoint.js','./stores/spfx-client.js','./stores/sharepoint-provisioning.js','./manifest.webmanifest'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request))));
